"use client";

import * as React from "react";
import { playStrip, preloadStrips } from "./cast-sprite";
import { SKIM_ART, SKIM_FRAMES } from "./skim-art";
import { StatusButton, type ActionStatus } from "./status-button";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * TERMS: Skim reads them with you
 *
 *   reading  Skim, an owl in reading glasses, sits on the lit
 *            stage with his book; his bubble gives the section
 *            you're on in one plain line ("Your files stay
 *            yours."), and changes as you scroll into the next
 *   dizzy    scroll too fast (or Skip to the end) and his eyes
 *            spin
 *   yawn     linger 4s on one section and he yawns, and again
 *            every 6s you stay
 *   read     reach the end: thumbs up, "Nothing sneaky", and
 *            Accept turns on
 *   accepted Accept → Accepting → Accepted
 *
 * The terms are your sections ({ title, body, tldr }); onAccept
 * gets the version so you can record which one was agreed to.
 * ───────────────────────────────────────────────────────── */

export interface TermsSection {
  id: string;
  title: string;
  body: React.ReactNode;
  /** The section in one plain line, in Skim's bubble. */
  tldr: string;
}

export interface TermsProps {
  sections: TermsSection[];
  /** Which terms these are; onAccept gets it back. */
  version: string;
  /** "Updated 21 October 2026", under the title. */
  updated?: string;
  /** Record the acceptance; throw to say it didn't save. */
  onAccept: (version: string) => Promise<unknown>;
  /** Shows Not now beside Accept. */
  onDecline?: () => void;
  /** Accept stays off until the terms have been scrolled to the end. */
  requireRead?: boolean;
  title?: string;
  /** What the owl is called in his lines. */
  name?: string;
  className?: string;
}

type Pose = "reading" | "dizzy" | "yawn" | "proud";

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface, ruled faintly like a page: he's reading, after all. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(70% 90% at 15% 100%, ${mix(PF, 20)} 0%, transparent 65%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 20)} 100%)`,
    `repeating-linear-gradient(180deg, transparent 0 17px, ${mix(PF, 9)} 17px 18px)`,
  ].join(", "),
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix(PF, 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix(PF, 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
/* one animation frame on the stage (he fills almost all of its height) */
const OWL_FRAME_H = 112;
const OWL_FRAME_W = (SKIM_FRAMES.w / SKIM_FRAMES.h) * OWL_FRAME_H;

/** A line that lifts out through a blur as the next one rises in (sentences don't letter-morph well). */
function Line({ text, reduced }: { text: string; reduced: boolean }) {
  const [shown, setShown] = React.useState([{ text, key: 0 }]);
  const [last, setLast] = React.useState(text);
  if (last !== text) {
    setLast(text);
    setShown((s) => [...s.slice(-1), { text, key: s[s.length - 1].key + 1 }]);
  }
  const mounted = React.useRef(false);
  React.useEffect(() => {
    mounted.current = true;
  }, []);
  return (
    <span className="grid">
      {shown.map((l, i) => {
        const current = i === shown.length - 1;
        return (
          <span
            key={l.key}
            className="col-start-1 row-start-1"
            aria-hidden={!current}
            ref={(el) => {
              if (!el || reduced) return;
              if (current && el.dataset.in !== "1" && mounted.current) {
                el.dataset.in = "1";
                el.animate(
                  [
                    {
                      opacity: 0,
                      transform: "translateY(5px)",
                      filter: "blur(4px)",
                    },
                    { opacity: 1, transform: "none", filter: "blur(0)" },
                  ],
                  {
                    duration: 360,
                    delay: 80,
                    easing: EASE_OUT,
                    fill: "backwards",
                  },
                );
              } else if (!current && el.dataset.out !== "1") {
                el.dataset.out = "1";
                el.animate(
                  [
                    { opacity: 1 },
                    {
                      opacity: 0,
                      transform: "translateY(-5px)",
                      filter: "blur(4px)",
                    },
                  ],
                  { duration: 200, easing: "ease-in", fill: "forwards" },
                ).onfinish = () =>
                  setShown((s) => s.filter((x) => x.key !== l.key));
              }
            }}
            style={reduced && !current ? { opacity: 0 } : undefined}
          >
            {l.text}
          </span>
        );
      })}
    </span>
  );
}

export function Terms({
  sections,
  version,
  updated,
  onAccept,
  onDecline,
  requireRead = true,
  title = "Terms of Service",
  name = "Skim",
  className = "",
}: TermsProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const pane = React.useRef<HTMLDivElement>(null);
  const bar = React.useRef<HTMLDivElement>(null);
  const owl = React.useRef<HTMLDivElement>(null);
  const [at, setAt] = React.useState(0);
  const [read, setRead] = React.useState(false);
  const [atEnd, setAtEnd] = React.useState(false);
  const [mood, setMood] = React.useState<"" | "dizzy" | "yawn">("");
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const last = React.useRef({ y: 0, t: 0 });
  const dizzyTimer = React.useRef(0);
  const yawnTimer = React.useRef(0);

  // linger on one section and he yawns: a 2.2s yawn after 4s without a scroll, then again every 6s you stay; any scroll wakes him
  const restartYawn = React.useCallback(() => {
    window.clearTimeout(yawnTimer.current);
    const yawn = (after: number) => {
      yawnTimer.current = window.setTimeout(() => {
        setMood((m) => (m === "" ? "yawn" : m));
        yawnTimer.current = window.setTimeout(() => {
          setMood((m) => (m === "yawn" ? "" : m));
          yawn(6000);
        }, 2400);
      }, after);
    };
    yawn(4000);
  }, []);
  React.useEffect(() => {
    restartYawn();
    return () => {
      window.clearTimeout(yawnTimer.current);
      window.clearTimeout(dizzyTimer.current);
    };
  }, [restartYawn]);

  const onScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const el = e.currentTarget;
    const max = el.scrollHeight - el.clientHeight;
    const k = max > 0 ? el.scrollTop / max : 1;
    bar.current?.style.setProperty("transform", `scaleX(${k})`);
    // too fast to read: his eyes spin
    const dy = Math.abs(el.scrollTop - last.current.y);
    const dt = e.timeStamp - last.current.t;
    last.current = { y: el.scrollTop, t: e.timeStamp };
    if (dy > el.clientHeight * 1.2 || (dt > 0 && dt < 120 && dy / dt > 1.8)) {
      setMood("dizzy");
      window.clearTimeout(dizzyTimer.current);
      dizzyTimer.current = window.setTimeout(() => setMood(""), 1100);
    } else setMood((m) => (m === "yawn" ? "" : m));
    restartYawn();
    // the section at the reading line, a third of the way down
    const line = el.scrollTop + el.clientHeight / 3;
    let i = 0;
    el.querySelectorAll<HTMLElement>("[data-section]").forEach((s, j) => {
      if (s.offsetTop <= line) i = j;
    });
    if (el.scrollTop >= max - 4) i = sections.length - 1;
    setAt(i);
    setAtEnd(el.scrollTop >= max - 4);
    if (el.scrollTop >= max - 4) setRead(true);
  };

  const skip = () => {
    const el = pane.current;
    if (!el) return;
    setMood("dizzy");
    window.clearTimeout(dizzyTimer.current);
    dizzyTimer.current = window.setTimeout(() => setMood(""), 1300);
    el.scrollTo({
      top: el.scrollHeight,
      behavior: reduced ? "auto" : "smooth",
    });
  };

  const accept = async () => {
    if (status === "pending" || status === "success") return;
    setStatus("pending");
    try {
      await onAccept(version);
      setStatus("success");
    } catch {
      setStatus("error");
    }
  };

  const pose: Pose =
    mood === "dizzy"
      ? "dizzy"
      : status === "success" || (atEnd && mood === "")
        ? "proud"
        : mood === "yawn"
          ? "yawn"
          : "reading";
  const [shownPose, setShownPose] = React.useState(pose);
  if (shownPose !== pose) setShownPose(pose);
  const sprite = React.useRef<HTMLDivElement>(null);
  React.useEffect(() => {
    preloadStrips(Object.values(SKIM_ART));
  }, []);
  // each pose is a loop of frames; the yawn plays once and he goes back to reading
  React.useEffect(() => {
    const clip = SKIM_FRAMES.clips[shownPose];
    playStrip(sprite.current, {
      src: SKIM_ART[shownPose],
      frames: clip.frames,
      fps: clip.fps,
      size: OWL_FRAME_W,
      height: OWL_FRAME_H,
      loop: shownPose !== "yawn",
      reduced,
    });
    if (!reduced && shownPose !== "yawn")
      owl.current?.animate(
        [
          { transform: "scale(0.96) translateY(2px)", opacity: 0.6 },
          { transform: "none", opacity: 1 },
        ],
        { duration: 260, easing: EASE_OUT },
      );
  }, [shownPose, reduced]);

  const say =
    status === "success"
      ? "Thanks for reading. Well, skimming."
      : pose === "dizzy"
        ? "Whoa. Slow down, I’m reading."
        : atEnd
          ? "That’s everything. Nothing sneaky."
          : pose === "yawn"
            ? `Still on ${sections[at]?.title.toLowerCase() ?? "this"}…`
            : (sections[at]?.tldr ?? "");
  const canAccept = !requireRead || read;

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative flex h-[132px] items-end overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          {/* Skim, animated: each pose is a loop of frames */}
          <div
            ref={owl}
            aria-hidden="true"
            className="relative mb-1 ml-1 shrink-0"
            style={{
              height: OWL_FRAME_H,
              width: OWL_FRAME_W,
              transformOrigin: "50% 100%",
            }}
          >
            <div ref={sprite} className="size-full" />
          </div>
          {/* his bubble: the section in one plain line */}
          <div className="relative mb-auto mr-3 mt-4 min-w-0 flex-1">
            <span
              aria-hidden="true"
              className="absolute -left-[5px] top-6 size-2.5 rotate-45 rounded-[2px]"
              style={{ background: PF }}
            />
            <div
              className="relative rounded-[14px] px-3 py-2"
              style={{ background: PF, color: "var(--primary)" }}
            >
              <p className="text-[11px] font-medium opacity-70">
                {name}’s summary · {Math.min(at + 1, sections.length)} of{" "}
                {sections.length}
              </p>
              <p
                className="mt-0.5 text-[13px] font-medium leading-[1.35] @max-[340px]:text-[12px]"
                aria-live="polite"
              >
                <Line text={say} reduced={reduced} />
              </p>
            </div>
          </div>
        </div>

        <div className="px-3 pt-3">
          <div className="flex items-baseline justify-between gap-3">
            <h2
              id={`${baseId}-title`}
              className="text-[15px] font-medium tracking-[-0.01em]"
            >
              {title}
            </h2>
            {!read && (
              <button
                type="button"
                onClick={skip}
                className="shrink-0 cursor-pointer text-[12px] text-muted-foreground underline decoration-border underline-offset-2 hover:text-foreground"
              >
                Skip to the end
              </button>
            )}
          </div>
          {updated && (
            <p className="mt-0.5 text-[12px] text-muted-foreground">
              {updated}
            </p>
          )}
        </div>

        {/* the terms themselves, with how far you've read along the bottom */}
        <div className="relative mx-2 mt-2.5 overflow-clip rounded-[14px] border border-border bg-background">
          <div
            ref={pane}
            tabIndex={0}
            role="region"
            aria-label={title}
            onScroll={onScroll}
            className="h-[188px] overflow-y-auto overscroll-contain px-3.5 py-3 text-[12.5px] leading-[1.6] text-muted-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-inset"
          >
            {sections.map((s, i) => (
              <div key={s.id} data-section className={i ? "mt-3.5" : ""}>
                <h3 className="text-[12.5px] font-medium text-foreground">
                  {i + 1}. {s.title}
                </h3>
                <div className="mt-1 [&_p+p]:mt-2">{s.body}</div>
              </div>
            ))}
          </div>
          <div className="absolute inset-x-0 bottom-0 h-px bg-border" />
          <div
            ref={bar}
            className="absolute inset-x-0 bottom-0 h-px origin-left bg-primary"
            style={{ transform: "scaleX(0)" }}
          />
        </div>

        <div className="flex items-center gap-2 px-2 pb-1 pt-3">
          {onDecline && (
            <StatusButton
              variant="outline"
              labels={{ idle: "Not now" }}
              onClick={onDecline}
              className="h-10 flex-1 text-[13.5px]"
              disabled={status === "pending"}
            />
          )}
          <StatusButton
            status={status}
            labels={{
              idle: canAccept ? "Accept" : "Read to the end to accept",
              pending: "Accepting",
              success: "Accepted",
              error: "Try again",
            }}
            onClick={accept}
            disabled={!canAccept}
            className="h-10 flex-[2] text-[13.5px] disabled:bg-[color-mix(in_oklab,var(--foreground)_7%,transparent)] disabled:text-muted-foreground"
            style={canAccept && status !== "error" ? LIT : undefined}
          />
        </div>
      </div>
    </section>
  );
}

export default Terms;

/* ─────────────────────────────────────────────────────────
 * CAST SPRITE: play a strip of animation frames on an element
 *
 * A strip is a row of frames in one image. Playing it
 * is one Web Animation of background-position in steps(), so
 * a looping idle costs no frame loop and no React renders;
 * reduced motion shows the first frame and nothing moves.
 * ───────────────────────────────────────────────────────── */

export interface StripPlay {
  /** The strip, as an image URL. */
  src: string;
  frames: number;
  fps: number;
  /** One frame's size on screen, in px (height defaults to width). */
  size: number;
  height?: number;
  /** Loop forever (an idle), or play once and hold the last frame. */
  loop?: boolean;
  /** Play a one-shot strip backwards, ending on its first frame. */
  reverse?: boolean;
  reduced?: boolean;
  /** Called once a one-shot strip has played. */
  onEnd?: () => void;
}

/** Show `play` on `el`, replacing whatever it was playing. Returns the animation, if any. */
export function playStrip(
  el: HTMLElement | null,
  play: StripPlay,
): Animation | null {
  if (!el) return null;
  el.getAnimations().forEach((a) => a.cancel());
  const {
    src,
    frames,
    fps,
    size,
    height = size,
    loop = true,
    reverse = false,
    reduced = false,
    onEnd,
  } = play;
  const width = frames * size;
  if (el.dataset.strip !== src) {
    el.dataset.strip = src;
    el.style.backgroundImage = `url("${src}")`;
  }
  el.style.backgroundSize = `${width}px ${height}px`;
  el.style.backgroundRepeat = "no-repeat";
  const end = -(frames - 1) * size;
  const rest = loop || reverse ? 0 : end;
  el.style.backgroundPosition = `${rest}px 0px`;
  if (reduced || frames < 2) {
    onEnd?.();
    return null;
  }
  // steps(end) shows the start value first and lands on the end value as it finishes (the resting style then holds it)
  const keys =
    reverse && !loop
      ? [
          { backgroundPosition: `${end}px 0px` },
          { backgroundPosition: "0px 0px" },
        ]
      : [
          { backgroundPosition: "0px 0px" },
          { backgroundPosition: `${loop ? -width : end}px 0px` },
        ];
  const a = el.animate(keys, {
    duration: ((loop ? frames : frames - 1) * 1000) / fps,
    iterations: loop ? Infinity : 1,
    easing: `steps(${loop ? frames : frames - 1}, end)`,
  });
  if (!loop && onEnd) a.onfinish = () => onEnd();
  return a;
}

/** Decode strips up front, so the first frame of each is there the moment it plays. */
export function preloadStrips(srcs: string[]) {
  for (const src of srcs) {
    const img = new Image();
    img.src = src;
    void img.decode?.().catch(() => {});
  }
}

/* Skim's art: an owl in reading glasses reading, yawning, dizzy, and giving a thumbs up. Each clip is a strip of square frames cut from a generated animation, keyed to
 * transparent WebP; every clip shares one crop, so frames line up across clips. As data URIs so
 * one install brings everything. */

export const SKIM_ART = {
  reading:
    "data:image/webp;base64,",
  yawn: "data:image/webp;base64,",
  dizzy:
    "data:image/webp;base64,",
  proud:
    "data:image/webp;base64,",
};

export const SKIM_FRAMES = {
  /** One frame, in image px. */
  w: 137,
  h: 150,
  clips: {
    reading: { frames: 10, fps: 8 },
    yawn: { frames: 19, fps: 8 },
    dizzy: { frames: 10, fps: 8 },
    proud: { frames: 6, fps: 8 },
  },
} as const;

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

